}","newString":"export interface PromptOptions {
  material: string;
  title: string;
  subject: string;
  count: number;
  distribution: Record<Difficulty, number>;
  types: QuestionType[];
  extra: string;
  /** learner level, from the profile */
  audience?: string;
  /** why the learner is studying, from the profile */
  purpose?: string;
  /** math & science subject: write questions with real math notation */
  isSTEM?: boolean;
  /** questions should use LaTeX ($…$) for equations */
  needsEquations?: boolean;
  /** questions may reference graphs and diagrams */
  needsGraphs?: boolean;
  /** the app renders LaTeX ($…$ and $$…$$) everywhere: display, print, answer key, notes, tags and explanations */
  supportsLaTeX?: boolean;
}","allowMultiple":false},{"oldString":"export function mathPromptSection(o: {
  isSTEM?: boolean;
  needsEquations?: boolean;
  needsGraphs?: boolean;
}) {
  const lines: string[] = [];
  if (o.needsEquations) {
    lines.push(
      "- Write ALL mathematical notation in LaTeX: inline math in $…$ (e.g. $x^2 + y^2 = r^2$, $\\frac{a}{b}$, $\\int_0^\\infty e^{-x}\\,dx$) and larger equations in $$…$$.",
      "- Keep ordinary words outside the math delimiters. Never use code blocks for equations.",
      "- Escape backslashes for valid JSON (e.g. \\\\frac in the raw file).",
    );
  } else if (o.isSTEM) {
    lines.push(
      "- This is a math/science subject: use clean plain notation (×, ÷, √, ², π, θ, ≤, ∑) that reads well as plain text.",
    );
  }
  if (o.needsGraphs) {
    lines.push(
      "- For graph or diagram questions, describe the graph clearly in words (axes, shape, key points, labels) — do NOT reference or invent images. The app can only show text and LaTeX.",
    );
  }
  return lines.length ? `\nMATH & SCIENCE NOTATION\n${lines.join("\n")}\n` : "";
}","newString":"export function mathPromptSection(o: {
  isSTEM?: boolean;
  needsEquations?: boolean;
  needsGraphs?: boolean;
  supportsLaTeX?: boolean;
}) {
  const lines: string[] = [];

  if (o.supportsLaTeX) {
    lines.push(
      "- The app renders LaTeX everywhere — in the question, options, answer key, explanations, notes, hints and tags — on screen and on paper.",
      "- Use LaTeX whenever you need an equation, symbol, formula, integral, sum, matrix, unit, or any other math notation.",
      "- Use inline math in $…$ (e.g. $x^2 + y^2 = r^2$, $\\frac{a}{b}$, $\\int_0^\\infty e^{-x}\\,dx$) and larger display equations in $$…$$.",
      "- Keep ordinary words outside the math delimiters. Never fake an equation with plain characters or put math inside a code block.",
      "- Escape backslashes for valid JSON (e.g. \\\\frac in the raw file).",
    );
  }

  if (o.needsEquations) {
    lines.push(
      "- Write ALL mathematical notation in LaTeX: inline math in $…$ (e.g. $x^2 + y^2 = r^2$, $\\frac{a}{b}$, $\\int_0^\\infty e^{-x}\\,dx$) and larger equations in $$…$$.",
      "- Keep ordinary words outside the math delimiters. Never use code blocks for equations.",
      "- Escape backslashes for valid JSON (e.g. \\\\frac in the raw file).",
    );
  } else if (o.isSTEM && !o.supportsLaTeX) {
    lines.push(
      "- This is a math/science subject: use clean plain notation (×, ÷, √, ², π, θ, ≤, ∑) that reads well as plain text.",
    );
  }

  if (o.needsGraphs) {
    lines.push(
      "- For graph or diagram questions, describe the graph clearly in words (axes, shape, key points, labels) — do NOT reference or invent images. The app can only show text and LaTeX.",
    );
  }
  return lines.length ? `\nMATH & SCIENCE NOTATION\n${lines.join("\n")}\n` : "";
}","allowMultiple":false}]}}


