.exam-paper-themed {
  border-top: 7px solid var(--exam-accent);
  background-image: linear-gradient(180deg, var(--exam-soft) 0, #fff 190px);
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
.exam-theme-module {
  border-radius: 1rem;
  background-image:
    radial-gradient(ellipse at 100% 0, color-mix(in srgb, var(--exam-accent) 10%, transparent), transparent 48%),
    linear-gradient(180deg, var(--exam-soft) 0, #fff 220px);
}
.exam-theme-field-notes {
  border-top-style: double;
  border-top-width: 8px;
  background-image: repeating-linear-gradient(180deg, transparent 0 31px, color-mix(in srgb, var(--exam-border) 38%, transparent) 32px, transparent 33px);
}
.exam-theme-lab-report {
  background-image:
    linear-gradient(color-mix(in srgb, var(--exam-border) 28%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--exam-border) 28%, transparent) 1px, transparent 1px),
    linear-gradient(180deg, var(--exam-soft), #fff 230px);
  background-size: 18px 18px, 18px 18px, auto;
}
.exam-theme-workbook {
  border-radius: 0.35rem 1rem 1rem 0.35rem;
  border-left: 9px solid var(--exam-accent);
  background-image: linear-gradient(90deg, var(--exam-soft), #fff 25%);
}
.exam-paper-themed .exam-question-number {
  display: inline-flex;
  min-width: 1.8em;
  height: 1.8em;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: var(--exam-accent);
  color: #fff;
  font-size: 0.88em;
}
.exam-theme-field-notes .exam-question {
  border-style: dashed;
}
.exam-theme-lab-report .exam-question {
  border-radius: 0.15rem;
}
.exam-theme-workbook .exam-question-prompt {
  color: color-mix(in srgb, var(--exam-accent) 86%, #111);
}

